package com.ilp.login;

import java.util.*;

// Checks.java: the trainer's helper. Students do NOT edit this file.
// It tests each step and tells the web page which steps are done.
public class Checks {
    public static final int TOTAL = 10;
    public static final String[] TITLES = { "Page title", "Username box", "Password box", "Login button", "Add your own user", "Check the user exists", "Check the password", "Welcome message", "Sign up a new user", "Password must be 6+ characters" };
    public static final String[] FILES = { "Step01Header.java", "Step02UsernameBox.java", "Step03PasswordBox.java", "Step04LoginButton.java", "Step05MyUser.java", "Step06UserExists.java", "Step07PasswordOk.java", "Step08Welcome.java", "Step09Register.java", "Step10StrongPassword.java" };
    public static final int[] DAYS = { 2, 2, 2, 2, 2, 2, 2, 2, 2, 2 };

    // Returns "done", "todo" or "error: message"
    public static String status(int n) {
        try {
            return test(n) ? "done" : "todo";
        } catch (Throwable e) {
            return "error: " + e.getClass().getSimpleName() + (e.getMessage() == null ? "" : ": " + e.getMessage());
        }
    }

    public static boolean done(int n) {
        return status(n).equals("done");
    }

    public static int doneCount() {
        int c = 0;
        for (int n = 1; n <= TOTAL; n++) if (done(n)) c++;
        return c;
    }

    static boolean test(int n) {
        switch (n) {
            case 1: return String.valueOf(Step01Header.header()).contains("<h1");
            case 2: return String.valueOf(Step02UsernameBox.usernameBox()).contains("name=\"username\"");
            case 3: return String.valueOf(Step03PasswordBox.passwordBox()).contains("type=\"password\"");
            case 4: return String.valueOf(Step04LoginButton.loginButton()).contains("<button");
            case 5: return Checks.addUserWorks();
            case 6: return Boolean.TRUE.equals(Step06UserExists.userExists(Map.of("a", "1"), "a")) && Boolean.FALSE.equals(Step06UserExists.userExists(Map.of("a", "1"), "b"));
            case 7: return Boolean.TRUE.equals(Step07PasswordOk.passwordOk(Map.of("a", "1"), "a", "1")) && Boolean.FALSE.equals(Step07PasswordOk.passwordOk(Map.of("a", "1"), "a", "2"));
            case 8: return String.valueOf(Step08Welcome.welcome("ravi")).contains("ravi");
            case 9: return Checks.registerWorks();
            case 10: return Boolean.FALSE.equals(Step10StrongPassword.strongPassword("abc")) && Boolean.TRUE.equals(Step10StrongPassword.strongPassword("abcdef"));
            default: return false;
        }
    }

    static boolean addUserWorks() {
        Map<String, String> users = new HashMap<>(Map.of("rajeev", "ilp123"));
        Step05MyUser.addMyUser(users);
        return users.size() > 1;
    }
    static boolean registerWorks() {
        Map<String, String> users = new HashMap<>();
        Step09Register.register(users, "x", "y");
        return "y".equals(users.get("x"));
    }
}
